			"LJ/lua/common/units/unitsTemplates/uel3001/uel3001.santp" => "-- Supreme Commander Overhaul FA Land Role Replacements 1.0.0\n-- Explicit same-faction role substitution: FA UEL0303 -> uel3001.\n-- Sanctuary's stock EDA class identity remains the runtime owner; every\n-- gameplay table below is pinned to the installed Forged Alliance source.\nUnitTemplate.additions = UnitTemplate.additions or {}\nUnitTemplate.additions.meshes = nil\nUnitTemplate.additions.rotators = nil\nUnitTemplate.additions.buildBeamBones = nil\nUnitTemplate.additions.faSourceContract = {\n    mapping = \"UEL0303 -> uel3001\",\n    substitution = true,\n    sourceArchive = \"gamedata/units.scd\",\n    sourceArchiveSha256 = \"c23a48d6b47043144baafc4c7f47b5a470392264f1bbaf962896923d58899c26\",\n    sourceLuaArchive = \"gamedata/lua.scd\",\n    sourceLuaArchiveSha256 = \"3632a3294fc01a07ebe017dfd12ce4ff655c2d019934f1d7a784fbc1d4f314bb\",\n    sourceProjectileArchive = \"gamedata/projectiles.scd\",\n    sourceProjectileArchiveSha256 = \"60d2732597cde9ef046a663c8d439e60844f967147e14737c7ad5a08c641be12\",\n    sourceBlueprint = \"units/UEL0303/UEL0303_unit.bp\",\n    sourceBlueprintSha256 = \"327d13c35da244c4beccda90e697cbd3f5220d9ad7fbafd04c342fa79a372d5a\",\n    sourceScript = \"units/UEL0303/UEL0303_Script.lua\",\n    sourceScriptSha256 = \"102f17046627fcb9806c11dad0c0e286718f86362bc126cb101d527decd4d761\",\n    class = { owner = \"unitsDefaultEDA\", name = \"EDALandUnit\" },\n    collision = {\n        -- SizeX/Y/Z are FA's world collision dimensions. Display.UniformScale\n        -- scales the mesh presentation; it is not applied to the unit body.\n        size = { x = 0.9, y = 1.2, z = 0.9 },\n        offset = { x = 0, y = 0, z = 0 },\n        sourceDisplayUniformScale = 0.7,\n        sourceBodyCollisionUsesBlueprintSize = true,\n        sanctuaryUnitBody = {\n            collisionOffset = { x = 0, y = 0.6, z = 0 },\n        },\n    },\n    selection = {\n        x = 0.55, z = 0.5,\n        centerX = 0, centerZ = -0.25,\n        thickness = 0.7,\n    },\n    defence = { health = 1200, regen = 0 },\n    economy = {\n        buildCostEnergy = 5400,\n        buildCostMass = 480,\n        buildTime = 2400,\n        shieldMaintenanceEnergy = 25,\n    },\n    intel = { visionRadius = 22 },\n    movement = {\n        sourceMotionType = \"RULEUMT_Land\",\n        acceleration = 4,\n        brake = 4,\n        speed = 4,\n        reverseSpeed = 0,\n        steerForce = 10,\n        turnRadius = 5,\n        turnRate = 150,\n        sourceAnimationWalkRate = 5,\n        sanctuaryAuthoredSpeed = 0.8,\n    },\n    audio = {\n        sourceAmbientMoveBank = \"UEL\",\n        sourceAmbientMoveCue = \"UEL0303_Move_Loop\",\n        sanctuaryWalkerDonor = \"uel3801\",\n        sanctuaryWalkerDonorTemplateSha256 = \"189c307051af4423f0ace168694b2a7f0087cb4e07e90943055af3031143a178\",\n        sanctuaryEngineEvent = \"aelu1335\",\n    },\n    shield = {\n        sourceClass = \"UnitShield\",\n        personal = true,\n        sourceOwnerShieldMesh = \"/units/uel0303/UEL0303_PersonalShield_mesh\",\n        sourceImpactEffects = \"UEFShieldHit01\",\n        max = 2200,\n        regen = 9,\n        regenStart = 3,\n        sourceEnergyDrainRechargeTime = 5,\n        sourceDamageRechargeTime = 60,\n        sourceDamageRechargeRestoresFullHealth = true,\n        sourceSize = 2.5,\n        sourceSizeSemantics = \"diameter\",\n        sourceVerticalOffset = 0,\n        sourceStartsOffField = true,\n        sourceStartsOffFieldRuntimeInert = true,\n        sourceInitialEnableRule = \"Shield.StartOn ~= false\",\n        sourceEffectiveInitialEnabled = true,\n        sourceCreationRuntime = \"lua/sim/Unit.lua\",\n        sourceCreationRuntimeSha256 = \"ced522e17b204aedfe196706fd3f3421af5f041cf692248ef56d43c97b52cd67\",\n        sourceColliderType = \"Box\",\n        sourceColliderFormula = \"SizeX/Y/Z * 0.75 at CollisionOffsetX/Y/Z\",\n        sourceColliderBlueprintScale = 0.75,\n        sourceColliderSize = { x = 0.675, y = 0.9, z = 0.675 },\n        sourceColliderOffset = { x = 0, y = 0, z = 0 },\n        sourcePassOverkillDamage = true,\n        sanctuaryPersonalCollider = \"Box\",\n        sanctuaryPersonalVisual = \"EDA sphere compatibility visual\",\n        sanctuaryCompatibilityVisualRadius = 1.25,\n        sanctuaryInitialToggleOwner = \"stock HostUnit:OnStopBeingBuilt\",\n    },\n    weapon = {\n        sourceLabel = \"HeavyPlasma01\",\n        sourceProjectile = \"TDFPlasmaHeavy04\",\n        sanctuaryProjectile = \"per303\",\n        damage = 50,\n        damageType = \"Normal\",\n        rateOfFire = 3,\n        rackCount = 2,\n        rackFireTogether = false,\n        muzzleSalvoSize = 1,\n        muzzleSalvoDelay = 0,\n        projectilesPerOnFire = 1,\n        shotsPerSecond = 3,\n        totalDps = 150,\n    },\n    projectilePresentation = {\n        simulationSource = \"TDFPlasmaHeavy04\",\n        dedicatedSanctuaryProjectile = \"per303\",\n        presentationSourceUnit = \"UEL0001\",\n        presentationSourceUnitBlueprint = \"units/UEL0001/UEL0001_unit.bp\",\n        presentationSourceUnitBlueprintSha256 = \"d23dfe5cd085a5d248dc0544bebbf9432316b16905ada26fe88a5280591dd406\",\n        presentationSourceUnitScript = \"units/UEL0001/UEL0001_script.lua\",\n        presentationSourceUnitScriptSha256 = \"b3118531641de2ddc4c30a1dd461913f83d6b13778cfb041d47a20c6b80f2169\",\n        presentationSourceWeaponLabel = \"RightZephyr\",\n        presentationSourceProjectile = \"LaserBotTerran01\",\n        presentationSourceProjectileBlueprint = \"projectiles/LaserBotTerran01/LaserBotTerran01_proj.bp\",\n        presentationSourceProjectileBlueprintSha256 = \"4a1d33796c7896993dbee6f3a309a4ff56fa0c97900b1e3f702aafcf363437fe\",\n        presentationSourceProjectileScript = \"projectiles/LaserBotTerran01/LaserBotTerran01_script.lua\",\n        presentationSourceProjectileScriptSha256 = \"e89c5430b392baf89703bf926ff71b862a1dd4d4b6126e06af4f031bd5f9bcac\",\n        currentCanonicalCommanderTarget = \"uel0000\",\n        currentCanonicalCommanderProjectile = \"pcd121\",\n        sanctuaryVisualDonorTemplate = \"LJ/lua/common/projectiles/projectilesTemplates/pcd121/pcd121.santp\",\n        sanctuaryVisualDonorTemplateSha256 = \"252536ffba44544195bde3ebfba00063a134b429801098c537559b1f6380773a\",\n        authoredPresentationScale = 0.65,\n        compatibilityPresentation = true,\n        exactFaVisualAssetPort = false,\n    },\n    limitations = {\n        sourceDeathRateRandomization = \"0.75-1.25 unavailable; nominal rate used\",\n        transportFoldRuntime = false,\n        disabledFiringBonesRuntime = false,\n        ownerMeshPhaseShieldShader = false,\n        sourceShieldImpactEmitterGraph = false,\n        sourceProjectileEmitterGraph = false,\n        sourcePassOverkillDamageRuntime = false,\n    },\n}\n\nUnitTemplate.general.displayName = \"Tier 3: Assault Bot\"\nUnitTemplate.general.name = \"Titan\"\nUnitTemplate.general.icon = { shape = \"land1\", symbol = \"direct\", tech = \"t3\" }\nUnitTemplate.general.iconUI = \"tech3_land1_direct.png\"\nUnitTemplate.general.iconUIBuildSortPriority = 80\nUnitTemplate.general.iconUIType = \"land\"\nUnitTemplate.general.orders = {\n    Assist = true,\n    Attack = true,\n    AttackMove = true,\n    Move = true,\n    Patrol = true,\n    Stop = true,\n}\n-- This table declares that the shield toggle exists.  The source blueprint's\n-- StartsOff field is runtime-inert; FA creates the shield whenever StartOn is\n-- not explicitly false, so Sanctuary's stock completion path correctly starts\n-- this personal shield enabled.\nUnitTemplate.general.toggles = { Shield = true }\n\nUnitTemplate.collisionInfo = {\n    centerOffset = { x = 0, y = 0.6, z = 0 },\n    collisionSize = { x = 0.9, y = 1.2, z = 0.9 },\n}\nUnitTemplate.footprint = { x = 0.9, y = 0.9 }\nUnitTemplate.defence = {\n    health = { max = 1200, regen = 0, value = 1200 },\n    shields = {\n        {\n            boneName = \"Root\",\n            name = \"Personal Shield\",\n            type = \"Personal\",\n            max = 2200,\n            value = 2200,\n            regen = 9,\n            regenDelay = 3,\n            rechargeTime = 60,\n            rechargeHPRatio = 1,\n            -- FA ShieldSize is a diameter; Sanctuary consumes direct radii.\n            radii = { x = 1.25, y = 1.25, z = 1.25 },\n            -- FA UnitShield uses 75% of blueprint SizeX/Y/Z at the source\n            -- collision offsets (all absent/zero for UEL0303).\n            collisionSize = { x = 0.675, y = 0.9, z = 0.675 },\n            collisionOffset = { x = 0, y = 0, z = 0 },\n            offset = { x = 0, y = 0, z = 0 },\n            scoFaTitanPersonalShield = true,\n            scoManualRechargeTime = 5,\n            scoEnergyDrainRechargeTime = 5,\n            scoDamageRechargeTime = 60,\n        },\n    },\n}\nUnitTemplate.economy = {\n    buildTime = 2400,\n    cost = { alloys = 480, energy = 5400 },\n    maintenanceConsumption = { energy = 25 },\n}\nUnitTemplate.intel = { visionRadius = 22 }\nUnitTemplate.audio = UnitTemplate.audio or {}\nUnitTemplate.audio.engine = { looping = true, name = \"aelu1335\" }\nUnitTemplate.movement = {\n    acceleration = 4,\n    deceleration = 4,\n    altitudeJitterFactor = 0,\n    bankFactor = 0,\n    collisionMaskDefault = { \"LandSmall\" },\n    collisionMaskSpawn = { \"LandSmall\" },\n    maxReverseDistance = 0,\n    orbitRange = 0,\n    orbitSpeed = 0,\n    preferredAltitude = 0,\n    referenceAltitude = \"Ground\",\n    rotationSpeed = 150,\n    sortOrder = 1,\n    speed = 4,\n    terrainAlignmentFactor = 1,\n    type = \"LegsLand\",\n}\nUnitTemplate.tags = {\n    \"ANTI_SURFACE\",\n    \"BUILDABLE_BY_T3_FACTORY\",\n    \"DIRECT_FIRE\",\n    \"EDA\",\n    \"LAND\",\n    \"MOBILE\",\n    \"SHIELD\",\n    \"TECH3\",\n    \"WALKER\",\n}\n\nUnitTemplate.visuals = UnitTemplate.visuals or {}\nUnitTemplate.visuals.selection = {\n    size = { x = 0.55, y = 0.5 },\n    offset = { x = 0, y = 0, z = -0.25 },\n}\nUnitTemplate.visuals.animations = {\n    walk = {\n        authoredSpeed = 0.8,\n        clipName = \"AnimWalk\",\n        sanAnimationPath = \"Units/uel3001/LOD0/uel3001.sananimation\",\n    },\n    death01 = {\n        clipName = \"AnimDeath01\",\n        sanAnimationPath = \"Units/uel3001/LOD0/uel3001.sananimation\",\n    },\n    death02 = {\n        clipName = \"AnimDeath02\",\n        sanAnimationPath = \"Units/uel3001/LOD0/uel3001.sananimation\",\n    },\n    fold = {\n        clipName = \"AnimFold\",\n        sanAnimationPath = \"Units/uel3001/LOD0/uel3001.sananimation\",\n    },\n}\nUnitTemplate.visuals.effectsPersistent = nil\nUnitTemplate.visuals.persistantEffects = nil\nif UnitTemplate.visuals.effectsInstant then\n    for _, effects in pairs(UnitTemplate.visuals.effectsInstant) do\n        for _, effect in ipairs(effects) do\n            effect.boneName = \"Root\"\n        end\n    end\nend\n\nUnitTemplate.weapons = {\n    {\n        aimControllers = {\n            -- Sanctuary AND-gates every controller.  Give the shared Torso\n            -- yaw exactly one owner, then let each muzzle own only its pitch.\n            {\n                aimBone = \"Torso\",\n                yawBone = \"Torso\",\n                aimTolerance = 2,\n                defaultYawAdjustment = 0,\n                leadTarget = true,\n                poseResetTime = 3,\n                projectileSpeed = 30,\n                solverType = \"LowArc\",\n                yawMin = -180,\n                yawMax = 180,\n                yawSpeed = 150,\n            },\n            {\n                aimBone = \"Muzzle_R\",\n                aimTolerance = 2,\n                defaultPitchAdjustment = 10,\n                leadTarget = true,\n                pitchBone = \"ArmR_B04\",\n                pitchMin = -80, pitchMax = 100,\n                pitchSpeed = 30,\n                poseResetTime = 3,\n                projectileSpeed = 30,\n                solverType = \"LowArc\",\n            },\n            {\n                aimBone = \"Muzzle_L\",\n                aimTolerance = 2,\n                defaultPitchAdjustment = 10,\n                leadTarget = true,\n                pitchBone = \"ArmL_B04\",\n                pitchMin = -80, pitchMax = 100,\n                pitchSpeed = 30,\n                poseResetTime = 3,\n                projectileSpeed = 30,\n                solverType = \"LowArc\",\n            },\n        },\n        muzzles = {\n            Muzzle_R = { aimController = \"Muzzle_R\" },\n            Muzzle_L = { aimController = \"Muzzle_L\" },\n        },\n        damage = 50,\n        damageRadius = 0,\n        damageType = \"Normal\",\n        firingRandomness = 0,\n        layerTargetLimits = { \"Land\", \"WaterSurface\" },\n        layerWeaponLimits = { \"Land\" },\n        muzzleGroupChargeDelay = 0,\n        muzzleGroupTimeOut = -1,\n        -- FA RackFireTogether=false: advance one single-muzzle rack per shot.\n        -- HostWeapon advances the muzzle-group index after each size-one salvo,\n        -- so this remains three total shots/second, not three shots per arm.\n        muzzleGroups = {\n            { muzzles = { \"Muzzle_R\" } },\n            { muzzles = { \"Muzzle_L\" } },\n        },\n        muzzleSalvoDelay = 0,\n        muzzleSalvoSize = 1,\n        projectileLifetime = 0.7666666666666667,\n        projectileTemplate = \"per303\",\n        rangeMax = 20,\n        rangeMin = 0,\n        rangeRingType = \"DirectFire\",\n        rangeTracking = 1.1,\n        reloadTime = 0.3333333333333333,\n        targetWaterLimits = \"Above\",\n        scoFaWaterGate = \"Above\",\n    },\n}", 
			"LJ/lua/host/units/unitsClasses/unitsDefaultEDA.lua" => "-- Supreme Commander Overhaul FA Land Role Replacements 1.0.0\n-- Keep uel3001 on its stock EDALandUnit class.  Stock completion owns its\n-- initially enabled personal shield; this appendix only owns Titan deaths.\nlocal SCO_FaRoleStockEdaDeathThread = HostEDALandUnit.DeathThread\n\nfunction HostEDALandUnit:DeathThread(overkillRatio)\n    if self.tpId ~= \"uel3001\" then\n        return SCO_FaRoleStockEdaDeathThread(self, overkillRatio)\n    end\n\n    local animations = self.tp and self.tp.visuals and self.tp.visuals.animations\n    local useFirst = ((self.id and self.id.index) or 0) % 2 == 0\n    local death = animations and (useFirst and animations.death01 or animations.death02)\n    if not death or not death.id then\n        error(\"UEL3001 Titan requires both hash-pinned source death clips\")\n    end\n    Engine.PlayAnimation(self.id, death.id, 0.1)\n    WaitSeconds(useFirst and 3.4 or 1.9)\n    return SCO_FaRoleStockEdaDeathThread(self, overkillRatio)\nend", 
			"LJ/lua/host/shield.lua" => "-- Supreme Commander Overhaul FA Land Role Replacements 1.0.0\n-- Exact UEL0303 UnitShield timing: damage pops require 60 paid seconds and\n-- restore full health; manual/power shutdowns preserve health and require five\n-- paid seconds.  An explicit damage state is required because Sanctuary clamps\n-- Entity health above zero and therefore cannot identify a pop from HP alone.\nlocal SCO_FaRoleStockShieldSetEnableable = HostShield.SetEnableable\nlocal SCO_FaRoleStockShieldTakeDamage = HostShield.TakeDamage\nlocal SCO_FaRoleStockShieldRechargeThread = HostShield.RechargeThread\n\nlocal function SCO_FaTitanShieldContract(shield)\n    return shield.owner\n        and shield.owner.tpId == \"uel3001\"\n        and shield.tp\n        and shield.tp.scoFaTitanPersonalShield == true\nend\n\nlocal function SCO_FaTitanEnergySatisfaction(shield)\n    local economy = shield.owner\n        and shield.owner.army\n        and shield.owner.army.economy\n    local energy = economy\n        and economy.resources\n        and economy.resources.energy\n    if not economy or not energy then\n        return 0\n    end\n    if not economy.isEnergyDown then\n        return 1\n    end\n    return math.max(0, math.min(energy.satisfaction or 0, 1))\nend\n\nlocal function SCO_FaTitanCancelTimers(shield)\n    if shield.rechargeThread then\n        KillThread(shield.rechargeThread)\n        shield.rechargeThread = nil\n    end\n    if shield.regenAfterDelayThread then\n        KillThread(shield.regenAfterDelayThread)\n        shield.regenAfterDelayThread = nil\n    end\nend\n\nlocal function SCO_FaTitanEnableRegen(shield, restoredHealth)\n    if restoredHealth >= shield:GetMaxHealth() or shield.regenDelay <= 0 then\n        shield:SetRegenEnabled(true)\n        return\n    end\n    shield:SetRegenEnabled(false)\n    shield.regenTimeOutTick = Tick + shield.regenDelay\n    shield.regenAfterDelayThread =\n        shield:NewThread(shield.RegenAfterDelayThread)\nend\n\nfunction HostShield:TakeDamage(damage)\n    if not SCO_FaTitanShieldContract(self) then\n        return SCO_FaRoleStockShieldTakeDamage(self, damage)\n    end\n    if self.canTakeDamage\n        and not self.rechargeThread\n        and damage >= self:GetHealth()\n    then\n        self.scoFaTitanRechargeKind = \"Damage\"\n        self.scoFaTitanRechargeProgress = 0\n        self.scoFaTitanOffHealth = nil\n    end\n    return SCO_FaRoleStockShieldTakeDamage(self, damage)\nend\n\nfunction HostShield:RechargeThread()\n    if not SCO_FaTitanShieldContract(self) then\n        return SCO_FaRoleStockShieldRechargeThread(self)\n    end\n\n    local rechargeKind = self.scoFaTitanRechargeKind or \"Energy\"\n    local rechargeSeconds = rechargeKind == \"Damage\"\n        and self.tp.scoDamageRechargeTime\n        or self.tp.scoEnergyDrainRechargeTime\n    local requiredProgress = rechargeSeconds * Constants.TickRate\n    local progress = self.scoFaTitanRechargeProgress or 0\n\n    while self.isEnableable and progress < requiredProgress do\n        progress = math.min(\n            progress + SCO_FaTitanEnergySatisfaction(self),\n            requiredProgress)\n        self.scoFaTitanRechargeProgress = progress\n        WaitTicks(1)\n    end\n\n    if not self.isEnableable then\n        self.rechargeThread = nil\n        return\n    end\n\n    local maximum = self:GetMaxHealth()\n    local restoredHealth = rechargeKind == \"Damage\"\n        and maximum\n        or math.min(self.scoFaTitanOffHealth or maximum, maximum)\n    if restoredHealth <= 0 then\n        restoredHealth = maximum\n    end\n    self:SetHealth(restoredHealth)\n    self:SetEnabled(true)\n    SCO_FaTitanEnableRegen(self, restoredHealth)\n    self.scoFaTitanRechargeKind = nil\n    self.scoFaTitanRechargeProgress = 0\n    self.scoFaTitanOffHealth = nil\n    self.rechargeThread = nil\nend\n\nfunction HostShield:SetEnableable(value, skipRecharge)\n    if not SCO_FaTitanShieldContract(self) then\n        return SCO_FaRoleStockShieldSetEnableable(self, value, skipRecharge)\n    end\n    if value == self.isEnableable then\n        return\n    end\n    self.isEnableable = value\n\n    if value then\n        if skipRecharge then\n            SCO_FaTitanCancelTimers(self)\n            self:SetHealth(self:GetMaxHealth())\n            self:SetEnabled(true)\n            self:SetRegenEnabled(true)\n            self.scoFaTitanRechargeKind = nil\n            self.scoFaTitanRechargeProgress = 0\n            self.scoFaTitanOffHealth = nil\n        else\n            self.scoFaTitanRechargeKind =\n                self.scoFaTitanRechargeKind or \"Energy\"\n            self.rechargeThread = self:NewThread(self.RechargeThread)\n        end\n        return\n    end\n\n    local damageRechargePending =\n        self.scoFaTitanRechargeKind == \"Damage\"\n    SCO_FaTitanCancelTimers(self)\n    if not damageRechargePending then\n        self.scoFaTitanRechargeKind = \"Energy\"\n        self.scoFaTitanRechargeProgress = 0\n        self.scoFaTitanOffHealth = math.min(\n            self:GetHealth(), self:GetMaxHealth())\n    end\n    self:SetEnabled(false)\n    self:SetRegenEnabled(false)\nend", 
			_ => appendix, 
		};
	}

	internal static string BuildProjectile(string name, string sourceId, string sourceBlueprintPath, string sourceBlueprintSha256, string sourceScriptPath, string sourceScriptSha256, string impactVfx, string trailVfx)
	{
		return "---@type ProjectileTemplate\nProjectileTemplate = {\n    collisionInfo = {\n        centerOffset = { x = 0, y = 0.5, z = 0 },\n        collisionSize = { x = 1, y = 1, z = 1 },\n    },\n    general = {\n        icon = \"projectile\",\n        name = \"" + name + "\",\n        tpId = \"per303\",\n    },\n    -- Stock projectile loading does not apply this field to its root hierarchy.\n    -- The canonical field-fix hierarchy dispatcher creates one presentation-only\n    -- child at this scale while root collision and simulation remain scale one.\n    nonUniformScale = { x = 0.65, y = 0.65, z = 0.65 },\n    visuals = {\n        mesh = { lod0distance = 60 },\n        onImpactEffects = {\n            { effects = { { particleName = \"" + impactVfx + "\" } } },\n        },\n        persistantEffects = {\n            {\n                effects = {\n                    {\n                        boneName = \"SCO_Titan_Commander_Projectile_Visual\",\n                        particleName = \"" + trailVfx + "\",\n                    },\n                },\n            },\n        },\n    },\n}\n\n-- Simulation source archive: gamedata/projectiles.scd\n-- Simulation source archive SHA-256: 60d2732597cde9ef046a663c8d439e60844f967147e14737c7ad5a08c641be12\n-- Simulation source ID: " + sourceId + "\n-- Simulation source blueprint: " + sourceBlueprintPath + "\n-- Simulation source blueprint SHA-256: " + sourceBlueprintSha256 + "\n-- Simulation source script: " + sourceScriptPath + "\n-- Simulation source script SHA-256: " + sourceScriptSha256 + "\n-- Presentation source unit: UEL0001 (RightZephyr)\n-- Presentation source unit blueprint SHA-256: d23dfe5cd085a5d248dc0544bebbf9432316b16905ada26fe88a5280591dd406\n-- Presentation source unit script SHA-256: b3118531641de2ddc4c30a1dd461913f83d6b13778cfb041d47a20c6b80f2169\n-- Presentation source projectile: LaserBotTerran01\n-- Presentation source projectile blueprint SHA-256: 4a1d33796c7896993dbee6f3a309a4ff56fa0c97900b1e3f702aafcf363437fe\n-- Presentation source projectile script SHA-256: e89c5430b392baf89703bf926ff71b862a1dd4d4b6126e06af4f031bd5f9bcac\n-- Current canonical UEF commander route: UEL0001 -> uel0000 -> pcd121\n-- Sanctuary visual donor: LJ/lua/common/projectiles/projectilesTemplates/pcd121/pcd121.santp\n-- Sanctuary visual donor SHA-256: 252536ffba44544195bde3ebfba00063a134b429801098c537559b1f6380773a\n-- Presentation contract: dedicated per303 child at uniform scale 0.65.\n-- Compatibility presentation only; this is not a 1:1 Forged Alliance visual-asset port.\n-- Supreme Commander Overhaul FA Land Role Replacements 1.0.0";
	}
}
